import assert from 'node:assert/strict';
import test from 'node:test';
import { readFile, mkdir } from 'node:fs/promises';
import { join } from 'node:path';
import { chromium } from '../mobile/node_modules/playwright/index.mjs';

// These exact envelopes are generated by PublicSnapshot against owned SQLite
// fixture state. They retain local-fixture scope and canonical Mesh values.
test('same-origin publication bytes display outage and retained settlement at phone/desktop widths', { timeout: 30000 }, async () => {
  const proof = process.env.MORSE_PUBLIC_SNAPSHOT_PROOF_DIRECTORY; assert(proof, 'owned publication-state fixture output required');
  const good = JSON.parse(await readFile(join(proof, 'publication-accepted.json'))), outage = JSON.parse(await readFile(join(proof, 'publication-unavailable.json')));
  const browser = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH });
  await mkdir(join(proof, 'screenshots'), { recursive: true });
  const errors = [];
  try {
    for (const width of [390, 1440]) {
      const page = await browser.newPage({ viewport: { width, height: 900 } });
      page.on('pageerror', e => errors.push(e.message));
      page.on('request', request => { if (!request.url().startsWith('file:') && !request.url().startsWith('data:')) errors.push(`External request: ${request.url()}`); });
      await page.route('**/network-data.js', route => route.fulfill({ contentType: 'text/javascript', body: `globalThis.MORSE_NETWORK_REPORT=${JSON.stringify(outage)};` }));
      await page.goto(new URL('./network.html', import.meta.url).href);
      assert.match(await page.locator('#report-status').textContent(), /Current snapshot unavailable/);
      assert.match(await page.locator('#report-detail').textContent(), /historical last-good.*not current balances/);
      assert.equal(await page.locator('.retained-slash-record').count(), 1);
      assert.match(await page.locator('.retained-slash-record').textContent(), /Recorded settled slash/);
      assert.match(await page.locator('#source-scope').textContent(), /Disposable local bank/);
      assert.equal(await page.evaluate(() => document.documentElement.scrollWidth > innerWidth), false);
      await page.screenshot({ path: join(proof, 'screenshots', `outage-${width}.png`), fullPage: true });
      await page.evaluate(value => MorseNetworkReport.mount(document, value), good);
      assert.equal(await page.locator('#report-status').textContent(), 'Local fixture preview');
      assert.equal(await page.locator('.retained-slash-record').count(), 1);
      const capacity = { ...outage, status: 'capacity-refused', refused_new_settled_observations: 1 };
      await page.evaluate(value => MorseNetworkReport.mount(document, value), capacity);
      assert.match(await page.locator('#report-status').textContent(), /history capacity reached/);
      assert.equal(await page.locator('.retained-slash-record').count(), 1);
      await page.evaluate(value => MorseNetworkReport.mount(document, value), { ...outage, current: good.current });
      assert.equal(await page.locator('#report-status').textContent(), 'Report unavailable');
      assert.equal(await page.locator('.retained-slash-record').count(), 0, 'malformed association clears previously rendered values');
      await page.close();
    }
    assert.deepEqual(errors, []);
    console.log('MORSE_PUBLIC_SNAPSHOT_BROWSER_OWNED_SQLITE_FIXTURE_390_1440_OUTAGE_RETAINED_SETTLEMENT');
  } finally { await browser.close(); }
});
